import { useState, useEffect } from 'react'

// Map language codes to their translation files
const translationModules = {
  en: () => import('../locales/en.json'),
  zu: () => import('../locales/zu.json'),
  xh: () => import('../locales/xh.json'),
  af: () => import('../locales/af.json'),
  nso: () => import('../locales/nso.json'),
  tn: () => import('../locales/tn.json'),
  st: () => import('../locales/st.json'),
  ts: () => import('../locales/ts.json'),
  ss: () => import('../locales/ss.json'),
  ve: () => import('../locales/ve.json'),
  nr: () => import('../locales/nr.json'),
  es: () => import('../locales/es.json'),
  fr: () => import('../locales/fr.json'),
  de: () => import('../locales/de.json'),
  pt: () => import('../locales/pt.json'),
  it: () => import('../locales/it.json'),
  nl: () => import('../locales/nl.json'),
}

export function useTranslation() {
  const [language, setLanguage] = useState(() => {
    return localStorage.getItem('language') || 'en'
  })
  const [translations, setTranslations] = useState({})
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    const loadTranslations = async () => {
      setLoading(true)
      try {
        const module = await translationModules[language]()
        setTranslations(module.default || module)
      } catch (error) {
        console.error('Error loading translations:', error)
        // Fallback to English
        try {
          const enModule = await translationModules.en()
          setTranslations(enModule.default || enModule)
        } catch (e) {
          setTranslations({})
        }
      } finally {
        setLoading(false)
      }
    }
    loadTranslations()
  }, [language])

  const t = (key) => {
    return translations[key] || key
  }

  return { t, language, setLanguage, loading }
}
